import {
  OutputFormatter,
  catchError
} from "./packager-tool-gkvdytpj.js";
import {
  getFileSystem
} from "./packager-tool-yv3rvyas.js";

// src/services/agent-builder-migrations.ts
var warnedLegacyToolGuardrailPolicies = false;
function migrateLegacyToolGuardrailPolicies(builder) {
  let migrated = false;
  for (const resource of builder.resources ?? []) {
    if (resource.$resourceType !== "tool" || !Array.isArray(resource.guardrailPolicies)) {
      continue;
    }
    if (!resource.guardrail?.policies?.length) {
      resource.guardrail = { policies: resource.guardrailPolicies };
      migrated = true;
    }
    delete resource.guardrailPolicies;
  }
  if (migrated && !warnedLegacyToolGuardrailPolicies) {
    OutputFormatter.log({
      Warning: "Migrated legacy guardrailPolicies to guardrail.policies."
    });
    warnedLegacyToolGuardrailPolicies = true;
  }
}

// src/services/agent-project-service.ts
class AgentProjectService {
  fs = getFileSystem();
  resolvedAgentDirs = new Map;
  getAgentDir(projectPath) {
    const cached = this.resolvedAgentDirs.get(projectPath);
    if (cached) {
      return cached;
    }
    return projectPath;
  }
  async resolveAgentDir(projectPath) {
    const cached = this.resolvedAgentDirs.get(projectPath);
    if (cached) {
      return cached;
    }
    const flatAgent = this.fs.path.join(projectPath, "agent.json");
    if (await this.fs.stat(flatAgent)) {
      this.resolvedAgentDirs.set(projectPath, projectPath);
      return projectPath;
    }
    const entries = await this.fs.readdir(projectPath);
    for (const entry of entries) {
      if (entry.startsWith(".") || entry === "evals" || entry === "features" || entry === "resources" || entry === "userProfile") {
        continue;
      }
      const candidate = this.fs.path.join(projectPath, entry);
      const candidateStat = await this.fs.stat(candidate);
      if (!candidateStat?.isDirectory())
        continue;
      const agentStat = await this.fs.stat(this.fs.path.join(candidate, "agent.json"));
      if (agentStat) {
        this.resolvedAgentDirs.set(projectPath, candidate);
        return candidate;
      }
    }
    this.resolvedAgentDirs.set(projectPath, projectPath);
    return projectPath;
  }
  async readAgentJson(projectPath) {
    const agentDir = this.getAgentDir(projectPath);
    const raw = await this.fs.readFile(this.fs.path.join(agentDir, "agent.json"), "utf-8");
    return JSON.parse(raw);
  }
  async writeAgentJson(projectPath, agent) {
    const agentDir = this.getAgentDir(projectPath);
    await this.fs.writeFile(this.fs.path.join(agentDir, "agent.json"), `${JSON.stringify(agent, null, 2)}
`);
    const builderDir = this.fs.path.join(agentDir, ".agent-builder");
    await this.safeMkdir(builderDir);
    let existingBuilder;
    const [builderReadError, builderRaw] = await catchError(this.fs.readFile(this.fs.path.join(builderDir, "agent.json"), "utf-8"));
    if (!builderReadError && builderRaw) {
      try {
        existingBuilder = JSON.parse(builderRaw);
        migrateLegacyToolGuardrailPolicies(existingBuilder);
      } catch {}
    }
    const builderAgent = {
      id: agent.projectId,
      name: existingBuilder?.name ?? "Agent",
      ...agent,
      resources: existingBuilder?.resources ?? agent.resources ?? [],
      features: existingBuilder?.features ?? agent.features ?? []
    };
    await this.fs.writeFile(this.fs.path.join(builderDir, "agent.json"), `${JSON.stringify(builderAgent, null, 2)}
`);
  }
  async readEntryPoints(projectPath) {
    const agentDir = this.getAgentDir(projectPath);
    const raw = await this.fs.readFile(this.fs.path.join(agentDir, "entry-points.json"), "utf-8");
    return JSON.parse(raw);
  }
  async writeEntryPoints(projectPath, entryPoints) {
    const agentDir = this.getAgentDir(projectPath);
    await this.fs.writeFile(this.fs.path.join(agentDir, "entry-points.json"), `${JSON.stringify(entryPoints, null, 2)}
`);
    const builderDir = this.fs.path.join(agentDir, ".agent-builder");
    await this.safeMkdir(builderDir);
    await this.fs.writeFile(this.fs.path.join(builderDir, "entry-points.json"), `${JSON.stringify(entryPoints, null, 2)}
`);
  }
  async readSolutionStorage(projectPath) {
    const raw = await this.fs.readFile(this.fs.path.join(projectPath, "SolutionStorage.json"), "utf-8");
    return JSON.parse(raw);
  }
  async writeSolutionStorage(projectPath, storage) {
    await this.fs.writeFile(this.fs.path.join(projectPath, "SolutionStorage.json"), `${JSON.stringify(storage, null, 2)}
`);
  }
  async readEvaluator(projectPath, fileName) {
    const filePath = this.fs.path.join(this.getAgentDir(projectPath), "evals", "evaluators", fileName);
    const raw = await this.fs.readFile(filePath, "utf-8");
    return JSON.parse(raw);
  }
  async writeEvaluator(projectPath, evaluator) {
    const dir = this.fs.path.join(this.getAgentDir(projectPath), "evals", "evaluators");
    await this.safeMkdir(dir);
    await this.fs.writeFile(this.fs.path.join(dir, evaluator.fileName), `${JSON.stringify(evaluator, null, 2)}
`);
  }
  async listEvaluators(projectPath) {
    const dir = this.fs.path.join(this.getAgentDir(projectPath), "evals", "evaluators");
    const [error, files] = await catchError(this.fs.readdir(dir));
    if (error) {
      return [];
    }
    const evaluators = [];
    for (const file of files) {
      if (file.endsWith(".json")) {
        const raw = await this.fs.readFile(this.fs.path.join(dir, file), "utf-8");
        evaluators.push(JSON.parse(raw));
      }
    }
    return evaluators;
  }
  async deleteEvaluator(projectPath, fileName) {
    const filePath = this.fs.path.join(this.getAgentDir(projectPath), "evals", "evaluators", fileName);
    await this.fs.rm(filePath);
  }
  async readEvalSet(projectPath, fileName) {
    const filePath = this.fs.path.join(this.getAgentDir(projectPath), "evals", "eval-sets", fileName);
    const raw = await this.fs.readFile(filePath, "utf-8");
    return JSON.parse(raw);
  }
  async writeEvalSet(projectPath, evalSet, fileName) {
    const dir = this.fs.path.join(this.getAgentDir(projectPath), "evals", "eval-sets");
    await this.safeMkdir(dir);
    await this.fs.writeFile(this.fs.path.join(dir, fileName), `${JSON.stringify(evalSet, null, 2)}
`);
  }
  async listEvalSets(projectPath) {
    const dir = this.fs.path.join(this.getAgentDir(projectPath), "evals", "eval-sets");
    const [error, files] = await catchError(this.fs.readdir(dir));
    if (error) {
      return [];
    }
    const sets = [];
    for (const file of files) {
      if (file.endsWith(".json")) {
        const raw = await this.fs.readFile(this.fs.path.join(dir, file), "utf-8");
        sets.push(JSON.parse(raw));
      }
    }
    return sets;
  }
  async deleteEvalSet(projectPath, fileName) {
    const filePath = this.fs.path.join(this.getAgentDir(projectPath), "evals", "eval-sets", fileName);
    await this.fs.rm(filePath);
  }
  async writeResource(projectPath, resourceName, resource) {
    const dir = this.fs.path.join(this.getAgentDir(projectPath), "resources", resourceName);
    await this.safeMkdir(dir);
    await this.fs.writeFile(this.fs.path.join(dir, "resource.json"), `${JSON.stringify(resource, null, 2)}
`);
  }
  async readResource(projectPath, resourceName) {
    const filePath = this.fs.path.join(this.getAgentDir(projectPath), "resources", resourceName, "resource.json");
    const raw = await this.fs.readFile(filePath, "utf-8");
    return JSON.parse(raw);
  }
  async listResourceDirs(projectPath) {
    const dir = this.fs.path.join(this.getAgentDir(projectPath), "resources");
    const [error, entries] = await catchError(this.fs.readdir(dir));
    if (error) {
      return [];
    }
    return entries;
  }
  async deleteResource(projectPath, resourceName) {
    const dir = this.fs.path.join(this.getAgentDir(projectPath), "resources", resourceName);
    await catchError(this.fs.rm(this.fs.path.join(dir, "resource.json")));
    await catchError(this.fs.rm(dir));
  }
  async writeFeature(projectPath, featureName, feature) {
    this.validateFeatureName(featureName);
    const dir = this.fs.path.join(this.getAgentDir(projectPath), "features", featureName);
    await this.safeMkdir(dir);
    await this.fs.writeFile(this.fs.path.join(dir, "feature.json"), `${JSON.stringify(feature, null, 2)}
`);
  }
  async readFeature(projectPath, featureName) {
    this.validateFeatureName(featureName);
    const filePath = this.fs.path.join(this.getAgentDir(projectPath), "features", featureName, "feature.json");
    const raw = await this.fs.readFile(filePath, "utf-8");
    if (!raw) {
      throw new Error(`Feature file not found: ${filePath}`);
    }
    const parsed = JSON.parse(raw);
    if (!parsed) {
      throw new Error(`Feature file is empty: ${filePath}`);
    }
    return parsed;
  }
  async listFeatureDirs(projectPath) {
    const dir = this.fs.path.join(this.getAgentDir(projectPath), "features");
    const [error, entries] = await catchError(this.fs.readdir(dir));
    if (error) {
      return [];
    }
    return entries;
  }
  async deleteFeature(projectPath, featureName) {
    this.validateFeatureName(featureName);
    const dir = this.fs.path.join(this.getAgentDir(projectPath), "features", featureName);
    await this.fs.rm(dir);
  }
  async writeSolutionConnectionResource(projectPath, opts) {
    const dir = this.fs.path.join(projectPath, "resources", "solution_folder", "connection", opts.connectorKey);
    await this.safeMkdir(dir);
    const fileName = `${opts.connectorName.replace(/ /g, "_")}.json`;
    await this.fs.writeFile(this.fs.path.join(dir, fileName), `${JSON.stringify({
      docVersion: "1.0.0",
      resource: {
        name: opts.connectorName,
        kind: "connection",
        type: opts.connectorKey,
        apiVersion: "integrationservice.uipath.com/v1",
        isOverridable: true,
        dependencies: [],
        runtimeDependencies: [],
        files: [],
        folders: [{ fullyQualifiedName: "solution_folder" }],
        spec: {
          connectorName: opts.connectorName,
          name: opts.connectorName,
          description: null,
          authenticationType: "AuthenticateAfterDeployment",
          connectorVersion: opts.connectorVersion ?? "1.0.0",
          connectorKey: opts.connectorKey,
          pollingInterval: 5
        },
        locks: [],
        key: opts.resourceKey
      }
    }, null, 2)}
`);
  }
  async findSolutionConnectionResourceKey(projectPath, connectorKey) {
    const dir = this.fs.path.join(projectPath, "resources", "solution_folder", "connection", connectorKey);
    const [error, files] = await catchError(this.fs.readdir(dir));
    if (error) {
      return;
    }
    for (const file of files) {
      if (file.endsWith(".json")) {
        const raw = await this.fs.readFile(this.fs.path.join(dir, file), "utf-8");
        const data = JSON.parse(raw);
        if (data?.resource?.key) {
          return data.resource.key;
        }
      }
    }
    return;
  }
  async projectExists(projectPath) {
    await this.resolveAgentDir(projectPath);
    const [error] = await catchError(this.fs.stat(this.fs.path.join(this.getAgentDir(projectPath), "agent.json")));
    if (error) {
      return false;
    }
    return true;
  }
  async validateProjectStructure(projectPath) {
    const errors = [];
    await this.resolveAgentDir(projectPath);
    const agentDir = this.getAgentDir(projectPath);
    const requiredFiles = [
      "agent.json",
      "entry-points.json",
      "project.uiproj"
    ];
    for (const file of requiredFiles) {
      const [statError] = await catchError(this.fs.stat(this.fs.path.join(agentDir, file)));
      if (statError) {
        errors.push(`Missing required file: Agent/${file}`);
      }
    }
    if (errors.length === 0 || !errors.some((e) => e.includes("agent.json"))) {
      const [agentError, agent] = await catchError(this.readAgentJson(projectPath));
      if (agentError) {
        errors.push(`Failed to parse agent.json: ${agentError.message}`);
      } else if (!agent) {
        errors.push("Failed to parse agent.json: file is empty or unreadable");
      } else {
        if (agent.type !== "lowCode") {
          errors.push(`agent.json type must be "lowCode", got "${agent.type}"`);
        }
        if (!agent.projectId) {
          errors.push("agent.json missing projectId");
        }
        if (!agent.messages || agent.messages.length === 0) {
          errors.push("agent.json missing messages");
        }
        if (!agent.metadata?.storageVersion) {
          errors.push("agent.json missing metadata.storageVersion");
        }
        if (!agent.settings?.model) {
          errors.push("agent.json missing settings.model");
        }
      }
    }
    const [solutionStatError] = await catchError(this.fs.stat(this.fs.path.join(projectPath, "SolutionStorage.json")));
    if (solutionStatError) {
      errors.push("Missing SolutionStorage.json at project root");
    }
    return { valid: errors.length === 0, errors };
  }
  async writeDebugOverwrites(projectPath, opts) {
    const dir = this.fs.path.join(projectPath, "userProfile", opts.userId);
    await this.safeMkdir(dir);
    const overwrites = {
      docVersion: "1.0.0",
      tenants: [
        {
          tenantKey: opts.tenantKey,
          resources: opts.resources.map((r) => ({
            solutionResourceKey: r.solutionResourceKey,
            reprovisioningIndex: 0,
            overwrite: {
              resourceKey: r.solutionResourceKey,
              resourceName: r.resourceName,
              folderKey: r.folderKey,
              folderFullyQualifiedName: r.folderFullyQualifiedName,
              folderPath: r.folderPath,
              type: "Reference",
              kind: "connection"
            }
          }))
        }
      ]
    };
    await this.fs.writeFile(this.fs.path.join(dir, "debug_overwrites.json"), `${JSON.stringify(overwrites, null, 2)}
`);
  }
  async readDebugOverwrites(projectPath, userId) {
    const filePath = this.fs.path.join(projectPath, "userProfile", userId, "debug_overwrites.json");
    const [error, raw] = await catchError(this.fs.readFile(filePath, "utf-8"));
    if (error || !raw) {
      return null;
    }
    const [parseError, parsed] = catchError(() => JSON.parse(raw));
    if (parseError) {
      return null;
    }
    return parsed;
  }
  async safeMkdir(dir) {
    await this.fs.mkdir(dir);
  }
  async writeJsonFile(filePath, data) {
    await this.fs.writeFile(filePath, `${JSON.stringify(data, null, 2)}
`);
  }
  validateFeatureName(featureName) {
    if (featureName.trim().length === 0 || featureName === "." || featureName === ".." || featureName.includes("/") || featureName.includes("\\") || featureName.includes("\x00") || featureName !== this.fs.path.basename(featureName)) {
      throw new Error(`Invalid feature name: "${featureName}"`);
    }
  }
}

export { migrateLegacyToolGuardrailPolicies, AgentProjectService };

